#!/usr/bin/env node
/**
 * Static gate for UPSC feature wiring.
 *
 * The product's learner loop was broken at the links, not the logic: the
 * retired day-room routes (`/upsc/{slug}/watch|talk|track|retro|revisit|
 * mcq-readiness`) were still being generated by live surfaces even though the
 * GS LMS is the study surface, the locked subjects' pages redirect into an LMS
 * layout that 404s anything but Geography, and the Current Affairs reviewer
 * action had no caller at all.
 *
 * There is no frontend test runner in this project, so this validator is the
 * regression cover, matching the pattern of
 * scripts/validate-optional-honest-failure.mjs.
 */

import { readFileSync, existsSync, readdirSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import path from 'node:path';
import process from 'node:process';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(HERE, '..');
const SRC = path.join(ROOT, 'src');

const checks = [];
function check(name, fn) {
  try {
    const detail = fn();
    checks.push({ name, ok: true, detail: detail ?? '' });
  } catch (error) {
    checks.push({ name, ok: false, detail: error.message });
  }
}

function sourceFiles(dir, out = []) {
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    if (entry.isDirectory()) {
      if (entry.name === 'node_modules') continue;
      sourceFiles(path.join(dir, entry.name), out);
    } else if (/\.(ts|tsx)$/.test(entry.name)) {
      out.push(path.join(dir, entry.name));
    }
  }
  return out;
}

/** Every `file:line` in src whose text matches `pattern`. */
function grepSrc(pattern) {
  const re = new RegExp(pattern);
  const hits = [];
  for (const file of sourceFiles(SRC)) {
    const rel = path.relative(ROOT, file).split(path.sep).join('/');
    readFileSync(file, 'utf8')
      .split(/\r?\n/)
      .forEach((line, index) => {
        if (re.test(line)) hits.push(`${rel}:${index + 1}: ${line.trim()}`);
      });
  }
  return hits;
}

/**
 * Components that are imported by nothing outside their own cluster are the
 * retired legacy-room cluster. They are pending a founder dead-code decision,
 * so their internal links are not a live defect and are excluded here.
 */
const RETIRED_CLUSTER = [
  'components/upsc/SubjectCommandRoom.tsx',
  'components/upsc/SubjectLabRoom.tsx',
  'components/upsc/SubjectLoopActions.tsx',
  'components/upsc/SubjectMcqReadinessRoom.tsx',
  'components/upsc/SubjectRetroRoom.tsx',
  'components/upsc/SubjectRevisitRoom.tsx',
  'components/upsc/SubjectTalkRoom.tsx',
  'components/upsc/SubjectTrackRoom.tsx',
  'components/upsc/SubjectWatchRoom.tsx',
  'components/dashboard/ZenDashboard.tsx',
  'components/upsc/UpscCurrentAffairsBridge.tsx',
];
const RETIRED_ROUTES = [
  ...RETIRED_CLUSTER,
  // Guided-study hrefs consumed only by the legacy rooms above.
  'lib/upsc/subjectGuidedStudy.ts',
  ...[
    'EnvironmentSubjectRoutes',
    'EconomySubjectRoutes',
    'HistorySubjectRoutes',
    'DisasterManagementSubjectRoutes',
    'InternalSecuritySocietySubjectRoutes',
    'PolityGovernanceSubjectRoutes',
    'ScienceTechSubjectRoutes',
  ].map((name) => `components/upsc/${name}.tsx`),
];

function isRetired(line) {
  return RETIRED_ROUTES.some((file) => line.includes(file));
}

const LEGACY_ROOM =
  '/upsc/\\$\\{[^}]*\\}/(watch|talk|track|retro|revisit|mcq-readiness|lab)';

check('no live surface links to a retired day room', () => {
  const hits = grepSrc(LEGACY_ROOM).filter((line) => !isRetired(line));
  if (hits.length) throw new Error(`${hits.length} link(s) remain:\n  ${hits.join('\n  ')}`);
  return 'retired day-room hrefs only remain inside the unreferenced legacy cluster';
});

check('the planner routes rooms onto real LMS tabs', () => {
  const engine = readFileSync(path.join(SRC, 'lib/upsc/dailyPlannerEngine.ts'), 'utf8');
  if (!/lmsHrefForRoom\(subjectSlug, room\)/.test(engine)) {
    throw new Error('routeFor() no longer delegates to lmsHrefForRoom()');
  }
  return 'dailyPlannerEngine.routeFor() uses the shared LMS room mapping';
});

check('every LMS destination in the room map has a page', () => {
  const routing = readFileSync(path.join(SRC, 'lib/upsc/lmsRoomRouting.ts'), 'utf8');
  const segments = [...routing.matchAll(/:\s*"([a-z-]+)",/g)].map((m) => m[1]);
  const unique = [...new Set(segments)];
  const missing = unique.filter(
    (segment) =>
      !existsSync(path.join(SRC, 'app/(dashboard)/upsc/[subject]/lms', segment, 'page.tsx')),
  );
  if (missing.length) throw new Error(`mapped to a segment with no page: ${missing.join(', ')}`);
  return `${unique.length} distinct LMS segments mapped, each with a page file`;
});

check('a locked subject explains itself instead of 404ing', () => {
  const layout = readFileSync(path.join(SRC, 'app/(dashboard)/upsc/[subject]/lms/layout.tsx'), 'utf8');
  if (/notFound\s*\(\s*\)\s*;/.test(layout)) {
    throw new Error('the LMS layout still raises notFound() for an unsupported subject');
  }
  if (!/SubjectNotOpen/.test(layout)) {
    throw new Error('the LMS layout has no honest not-open state for unsupported subjects');
  }
  return 'unsupported subject slugs render the not-open panel';
});

check('the CA reviewer can move an item through review from the list', () => {
  const cms = readFileSync(path.join(SRC, 'app/(dashboard)/admin/cms/page.tsx'), 'utf8');
  if (!/adminCmsService\.updateStatus\(/.test(cms)) {
    throw new Error('the CMS list never calls updateStatus(), so the review workflow is unreachable');
  }
  if (/\/admin\/cms\/\$\{item\.id\}/.test(cms)) {
    throw new Error('the CMS list still links to /admin/cms/{id}, a route with no page');
  }
  if (!/catch/.test(cms) || !/could not be loaded/.test(cms)) {
    throw new Error('the CMS list reports a failed read as an empty queue');
  }
  return 'status transitions are callable from the list and a failed read is shown as a failure';
});

check('the CA status map matches the backend engine contract', () => {
  const engine = readFileSync(
    path.join(ROOT, '..', 'backend', 'app', 'core', 'current_affairs', 'ca_engine.py'),
    'utf8',
  );
  const cms = readFileSync(path.join(SRC, 'app/(dashboard)/admin/cms/page.tsx'), 'utf8');
  const publishedAllowed = /ReviewStatus\.PUBLISHED:\s*\{ReviewStatus\.ARCHIVED\}/.test(engine);
  if (!publishedAllowed) throw new Error('backend VALID_TRANSITIONS changed; re-read the contract');
  for (const transition of [
    ["DRAFT: [{ to: 'IN_REVIEW'", 'DRAFT->IN_REVIEW'],
    ["to: 'PUBLISHED'", 'IN_REVIEW->PUBLISHED'],
    ["to: 'ARCHIVED'", 'PUBLISHED->ARCHIVED'],
  ]) {
    if (!cms.includes(transition[0])) throw new Error(`CMS is missing ${transition[1]}`);
  }
  return 'DRAFT->IN_REVIEW->PUBLISHED->ARCHIVED, plus return-to-draft, mirror VALID_TRANSITIONS';
});

let failed = 0;
for (const result of checks) {
  if (!result.ok) failed += 1;
  console.log(`${result.ok ? 'PASS' : 'FAIL'}  ${result.name}${result.detail ? ` — ${result.detail}` : ''}`);
}

if (failed) {
  console.error(`\n[validate-upsc-feature-wiring] ${failed} check(s) failed.`);
  process.exit(1);
}
console.log(
  `\n[validate-upsc-feature-wiring] PASS: ${checks.length} wiring checks passed across the UPSC learner and reviewer surfaces.`,
);
